 if(id===null){const data=new FormData();const transformed=items.map(d=>payload({...d,status:mode==='completed'?'done':'pending',completed_on:mode==='completed'?performed:'',kilometers:mode==='completed'?km:'',next_on:mode==='completed'?d.next_on:'',next_km:mode==='completed'?d.next_km:''}));const amount=cents(paid);if(transformed.every(i=>i.cost_status==='confirmed')&&amount>transformed.reduce((sum,i)=>sum+(i.amount_centimes??0),0))throw new Error('Le paiement dépasse le coût confirmé.');for(const [k,v]of Object.entries({mode,performed_on:performed,kilometers:km,garage,notes,paid_centimes:String(amount),paid_on:amount?paidOn:'',method:amount?method:'',payment_due_on:due,items:JSON.stringify(transformed),request_key:key.current})){if(v!=='')data.append(k,v);}if(file)data.append('file',file);body=data;path+='/files';
 }else if(operation==='work'){body={...payload(work),item_key:work.item_key,legacy_edit:editing&&!!work.legacy,revision:record!.revision,request_key:key.current};path+='/'+id+'/work';}
